/**
 * public/js/brain-canvas-worker.js  v1.0
 * =========================================
 * OffscreenCanvas Web Worker — GPU-accelerated Brain Neural Network Renderer
 *
 * Runs entirely on a dedicated Worker thread, offloading all canvas draw
 * operations from the main thread. The browser composites the OffscreenCanvas
 * result directly via GPU (Chromium uses the same compositor path as WebGL).
 *
 * GPU selection priority (enforced by powerPreference hint on WebGL probe):
 *   1. Dedicated GPU + VRAM   → OffscreenCanvas Worker + GPU compositor
 *   2. Integrated GPU (iGPU)  → OffscreenCanvas Worker + iGPU compositor
 *   3. CPU software renderer  → Fallback to main-thread Canvas 2D
 *
 * Messages IN  (from main thread):
 *   { type: 'init',    canvas: OffscreenCanvas, dpr, width, height, dark }
 *   { type: 'resize',  width, height, dpr }
 *   { type: 'pointer', x, y, isHovered }
 *   { type: 'theme',   dark }
 *   { type: 'click',   x, y }
 *   { type: 'region',  key }   — activeRegionKey from hit-test on main thread
 *
 * Messages OUT (to main thread):
 *   { type: 'ready' }
 *   { type: 'region', key }    — to trigger tooltip update on main thread
 */

