function classifyRegion(x, y) {
  if (y > 0.82) return 'brainstem';
  if (y >= 0.65 && x <= 0.48) return 'cerebellum';
  if (x < 0.28 && y < 0.65) return 'occipital';
  if ((x > 0.58 && y < 0.45) || (x > 0.70 && y < 0.62)) return 'frontal';
  if (0.28 <= x && x <= 0.65 && y < 0.40) return 'parietal';
  return 'temporal';
}

// ── Worker State ───────────────────────────────────────────────────────────
let canvas = null, ctx = null;
let dpr = 1, width = 0, height = 0;
let isDark = false;
let animId = null;
let isVisible = true;

let nodes = [], edges = [], pulses = [];
const regionGlow = { frontal: 0, parietal: 0, temporal: 0, occipital: 0, cerebellum: 0, brainstem: 0 };
let activeRegionKey = null;

let mouse = { x: -9999, y: -9999, isHovered: false, targetRotX: 0, targetRotY: 0, currentRotX: 0, currentRotY: 0, lastPulseTime: 0 };
let smoothPointer = { x: -9999, y: -9999, active: 0 };

const MAX_PULSES = 10;
const HOVER_RADIUS = 145;

// ── Build brain model ──────────────────────────────────────────────────────
function initBrainModel() {
  const rawNodes = BRAIN_DATA.nodes;
  const rawEdges = BRAIN_DATA.edges;

  nodes = rawNodes.map((n, idx) => {
    const cx = n[0] - 0.5;
    const cy = n[1] - 0.5;
    const r2 = Math.max(0, 0.28 - (cx * cx * 0.9 + cy * cy * 1.1));
    const z = Math.sqrt(r2) * (idx % 2 === 0 ? 1 : 0.85);
    return {
      id: idx,
      origX: n[0], origY: n[1], origZ: z,
      region: classifyRegion(n[0], n[1]),
      screenX: 0, screenY: 0, screenZ: 0,
      phase: Math.random() * Math.PI * 2,
      floatSpeed: 0.7 + Math.random() * 0.8,
      flare: 0, hoverActive: 0, neighbors: []
    };
  });

  edges = rawEdges.map(([i, j]) => {
    if (nodes[i] && nodes[j]) {
      nodes[i].neighbors.push(j);
      nodes[j].neighbors.push(i);
    }
    return [i, j];
  });

  pulses = [];
  for (let p = 0; p < MAX_PULSES; p++) spawnPulse();
}

function spawnPulse(startIdx = null) {
  if (pulses.length >= MAX_PULSES + 4) return;
  const fromIdx = startIdx !== null ? startIdx : Math.floor(Math.random() * nodes.length);
  const node = nodes[fromIdx];
  if (!node || node.neighbors.length === 0) return;
  const toIdx = node.neighbors[Math.floor(Math.random() * node.neighbors.length)];
  pulses.push({ from: fromIdx, to: toIdx, progress: Math.random() * 0.3, speed: 0.013 + Math.random() * 0.015 });
}

// ── Render (identical logic as main thread version) ────────────────────────
function render(timestamp) {
  animId = requestAnimationFrame(render);
  if (!isVisible || !ctx) return;

  ctx.clearRect(0, 0, width, height);

  const dark = isDark;
  const time = (timestamp || 0) * 0.001;

  if (mouse.isHovered) {
    if (smoothPointer.x < -1000) { smoothPointer.x = mouse.x; smoothPointer.y = mouse.y; }
    smoothPointer.x += (mouse.x - smoothPointer.x) * 0.12;
    smoothPointer.y += (mouse.y - smoothPointer.y) * 0.12;
    smoothPointer.active += (1 - smoothPointer.active) * 0.08;
  } else {
    smoothPointer.active += (0 - smoothPointer.active) * 0.05;
    if (smoothPointer.active < 0.002) { smoothPointer.active = 0; smoothPointer.x = -9999; smoothPointer.y = -9999; }
  }

  for (const rKey in regionGlow) {
    const targetGlow = activeRegionKey === rKey ? 1.0 : 0.0;
    regionGlow[rKey] += (targetGlow - regionGlow[rKey]) * 0.11;
  }

  mouse.currentRotX += (mouse.targetRotX - mouse.currentRotX) * 0.05;
  mouse.currentRotY += (mouse.targetRotY - mouse.currentRotY) * 0.05;

  const breathY = Math.sin(time * 0.55) * 0.02 + mouse.currentRotY;
  const breathX = Math.cos(time * 0.45) * 0.014 + mouse.currentRotX;
  const breathScale = 1.0 + Math.sin(time * 0.8) * 0.007;

  const paddingX = width * 0.02;
  const paddingY = height * 0.02;
  const drawW = (width - paddingX * 2) * breathScale;
  const drawH = (height - paddingY * 2) * breathScale;
  const offsetX = (width - drawW) * 0.5;
  const offsetY = (height - drawH) * 0.5;

  const cosY = Math.cos(breathY), sinY = Math.sin(breathY);
  const cosX = Math.cos(breathX), sinX = Math.sin(breathX);

  const smX = smoothPointer.x, smY = smoothPointer.y, smActive = smoothPointer.active;

  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    const floatX = Math.sin(time * n.floatSpeed + n.phase) * 0.0018;
    const floatY = Math.cos(time * n.floatSpeed + n.phase) * 0.0018;
    let x = n.origX - 0.5 + floatX;
    let y = n.origY - 0.5 + floatY;
    let z = n.origZ;
    let x1 = x * cosY - z * sinY;
    let z1 = x * sinY + z * cosY;
    let y2 = y * cosX - z1 * sinX;
    let z2 = y * sinX + z1 * cosX;
    n.screenX = offsetX + (x1 + 0.5) * drawW;
    n.screenY = offsetY + (y2 + 0.5) * drawH;
    n.screenZ = z2;

    if (smActive > 0.01 && smX > -1000) {
      const d = Math.hypot(n.screenX - smX, n.screenY - smY);
      const targetHover = d < HOVER_RADIUS ? Math.pow(1 - d / HOVER_RADIUS, 1.5) * smActive : 0;
      n.hoverActive += (targetHover - n.hoverActive) * 0.11;
    } else {
      n.hoverActive = Math.max(0, n.hoverActive * 0.92 - 0.002);
    }
    if (n.flare > 0) n.flare = Math.max(0, n.flare - 0.03);
  }

  const baseColor = dark ? 'rgba(217, 119, 87, 0.16)' : 'rgba(150, 130, 120, 0.22)';
  const lowTier = [], midTier = [], highTier = [];

  ctx.lineWidth = 0.65;
  ctx.strokeStyle = baseColor;
  ctx.beginPath();
  for (let e = 0; e < edges.length; e++) {
    const u = nodes[edges[e][0]], v = nodes[edges[e][1]];
    if (!u || !v) continue;
    ctx.moveTo(u.screenX, u.screenY);
    ctx.lineTo(v.screenX, v.screenY);
    const cursorEh = (u.hoverActive + v.hoverActive) * 0.5;
    const regEh = (u.region === v.region && regionGlow[u.region]) ? regionGlow[u.region] * 0.85 : 0;
    const eh = Math.max(cursorEh, regEh);
    if (eh > 0.65) highTier.push(u, v);
    else if (eh > 0.35) midTier.push(u, v);
    else if (eh > 0.06) lowTier.push(u, v);
  }
  ctx.stroke();

  if (lowTier.length > 0) {
    ctx.lineWidth = 0.85; ctx.strokeStyle = 'rgba(217, 119, 87, 0.28)'; ctx.beginPath();
    for (let i = 0; i < lowTier.length; i += 2) { ctx.moveTo(lowTier[i].screenX, lowTier[i].screenY); ctx.lineTo(lowTier[i + 1].screenX, lowTier[i + 1].screenY); }
    ctx.stroke();
  }
  if (midTier.length > 0) {
    ctx.lineWidth = 1.15; ctx.strokeStyle = 'rgba(217, 119, 87, 0.60)'; ctx.beginPath();
    for (let i = 0; i < midTier.length; i += 2) { ctx.moveTo(midTier[i].screenX, midTier[i].screenY); ctx.lineTo(midTier[i + 1].screenX, midTier[i + 1].screenY); }
    ctx.stroke();
  }
  if (highTier.length > 0) {
    ctx.lineWidth = 2.8; ctx.strokeStyle = 'rgba(217, 119, 87, 0.26)'; ctx.beginPath();
    for (let i = 0; i < highTier.length; i += 2) { ctx.moveTo(highTier[i].screenX, highTier[i].screenY); ctx.lineTo(highTier[i + 1].screenX, highTier[i + 1].screenY); }
    ctx.stroke();
    ctx.lineWidth = 1.45; ctx.strokeStyle = 'rgba(217, 119, 87, 0.92)'; ctx.beginPath();
    for (let i = 0; i < highTier.length; i += 2) { ctx.moveTo(highTier[i].screenX, highTier[i].screenY); ctx.lineTo(highTier[i + 1].screenX, highTier[i + 1].screenY); }
    ctx.stroke();
  }

  const pulseCore = dark ? '#ffffff' : '#D97757';
  const pulseGlow = 'rgba(217, 119, 87, 0.45)';
  for (let p = pulses.length - 1; p >= 0; p--) {
    const pulse = pulses[p];
    const fn = nodes[pulse.from], tn = nodes[pulse.to];
    if (!fn || !tn) { pulses.splice(p, 1); spawnPulse(); continue; }
    pulse.progress += pulse.speed;
    if (pulse.progress >= 1.0) {
      tn.flare = 0.8;
      if (tn.neighbors.length > 0 && Math.random() < 0.65) {
        pulse.from = pulse.to;
        pulse.to = tn.neighbors[Math.floor(Math.random() * tn.neighbors.length)];
        pulse.progress = 0; pulse.speed = 0.012 + Math.random() * 0.016;
      } else { pulses.splice(p, 1); spawnPulse(); continue; }
    }
    const px = fn.screenX + (tn.screenX - fn.screenX) * pulse.progress;
    const py = fn.screenY + (tn.screenY - fn.screenY) * pulse.progress;
    ctx.fillStyle = pulseGlow; ctx.beginPath(); ctx.arc(px, py, 4.2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = pulseCore; ctx.beginPath(); ctx.arc(px, py, 1.8, 0, Math.PI * 2); ctx.fill();
  }

  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    const sx = n.screenX, sy = n.screenY;
    const regG = regionGlow[n.region] || 0;
    const h = Math.max(n.hoverActive, regG * 0.85);
    const ringR = 2.6 + h * 3.4;
    const ringAlpha = Math.min(1.0, 0.22 + h * 0.75);
    const dotR = 1.2 + h * 0.9;
    if (h > 0.04) { ctx.fillStyle = `rgba(217, 119, 87, ${h * 0.25})`; ctx.beginPath(); ctx.arc(sx, sy, ringR + 2.8, 0, Math.PI * 2); ctx.fill(); }
    ctx.lineWidth = 0.5 + h * 0.65;
    ctx.strokeStyle = h > 0.04 ? `rgba(217, 119, 87, ${ringAlpha})` : (dark ? 'rgba(217, 119, 87, 0.25)' : 'rgba(165, 140, 130, 0.32)');
    ctx.beginPath(); ctx.arc(sx, sy, ringR + n.flare * 1.5, 0, Math.PI * 2); ctx.stroke();
    if (h > 0.3) {
      ctx.fillStyle = h > 0.7 ? '#ffffff' : `rgba(217, 119, 87, ${0.7 + h * 0.3})`;
    } else {
      const baseAlpha = 0.35 + n.screenZ * 0.25 + n.flare * 0.5;
      ctx.fillStyle = dark ? `rgba(235, 230, 222, ${Math.min(1, baseAlpha)})` : `rgba(60, 48, 40, ${Math.min(1, baseAlpha)})`;
    }
    ctx.beginPath(); ctx.arc(sx, sy, dotR + n.flare * 1.2, 0, Math.PI * 2); ctx.fill();
  }
}

// ── Hit-test on pointer event (runs in worker) ─────────────────────────────
function handlePointerInWorker(x, y, isHovered) {
  mouse.x = x; mouse.y = y; mouse.isHovered = isHovered;
  if (!isHovered) { mouse.targetRotX = 0; mouse.targetRotY = 0; activeRegionKey = null; return; }

  const normX = ((x / width) - 0.5) * 2;
  const normY = ((y / height) - 0.5) * 2;
  mouse.targetRotY = normX * 0.12;
  mouse.targetRotX = -normY * 0.08;

  let closestDist = Infinity, closestNode = null;
  for (let i = 0; i < nodes.length; i++) {
    const d = Math.hypot(nodes[i].screenX - x, nodes[i].screenY - y);
    if (d < closestDist) { closestDist = d; closestNode = nodes[i]; }
  }
  const newRegion = (closestDist < HOVER_RADIUS * 1.18 && closestNode) ? closestNode.region : null;
  if (newRegion !== activeRegionKey) {
    activeRegionKey = newRegion;
    self.postMessage({ type: 'region', key: activeRegionKey });
  }

  const now = performance.now();
  if (now - mouse.lastPulseTime > 130 && closestNode && closestDist < HOVER_RADIUS) {
    mouse.lastPulseTime = now;
    closestNode.flare = 0.8;
    spawnPulse(closestNode.id);
  }
}

// ── Message handler ────────────────────────────────────────────────────────
self.onmessage = function (e) {
  const msg = e.data;
  switch (msg.type) {
    case 'init':
      canvas = msg.canvas;
      isDark = msg.dark;
      dpr = msg.dpr || 1;
      width = msg.width;
      height = msg.height;
      ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.scale(dpr, dpr);
        initBrainModel();
        animId = requestAnimationFrame(render);
        self.postMessage({ type: 'ready' });
      }
      break;

    case 'resize':
      width = msg.width;
      height = msg.height;
      dpr = msg.dpr || 1;
      if (canvas) {
        canvas.width = Math.round(width * dpr);
        canvas.height = Math.round(height * dpr);
        if (ctx) { ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.scale(dpr, dpr); }
      }
      break;

    case 'pointer':
      handlePointerInWorker(msg.x, msg.y, msg.isHovered);
      break;

    case 'click': {
      const cx = msg.x, cy = msg.y;
      const near = [];
      for (let i = 0; i < nodes.length; i++) {
        const d = Math.hypot(nodes[i].screenX - cx, nodes[i].screenY - cy);
        if (d < HOVER_RADIUS * 1.2) near.push({ id: i, d });
      }
      near.sort((a, b) => a.d - b.d);
      for (let k = 0; k < Math.min(4, near.length); k++) {
        nodes[near[k].id].flare = 1.0;
        spawnPulse(near[k].id);
      }
      break;
    }

    case 'theme':
      isDark = msg.dark;
      break;

    case 'visibility':
      isVisible = msg.visible;
      break;
  }
};

